#include <bits/stdc++.h>
using namespace std;
static const int mod=998244353;
int main() {
	int t;cin>>t;
	while(t--){
	    int n;cin>>n;
	    vector<int>a(n+1);
	    vector<int>cnt(n+2,0);
	    for(int i=1;i<=n;i++){
	        cin>>a[i];
	        cnt[a[i]]++;
	    }
	    vector<int>start(n+2,0),idx(n);
	    for(int v=1;v<=n;v++)start[v+1]=start[v]+cnt[v];
	        {
	            vector<int>pos(start.begin(),start.end());
	            for(int i=1;i<=n;i++){
	                idx[pos[a[i]]++]=i;
	            }
	        }
	        vector<int>dp(n+2,0),nd(n+2,0);
	        vector<char>l(n+2),r(n+2);
	        dp[0]=1;
	        long long ans=0;
	        for(int v=1;v<=n;v++){
	            for(int x=0;x<v;x++){
	                l[x]=r[x]=1;
	            }
	            for(int p=start[v];p<start[v+1];p++){
	              int i=idx[p];
	              int c=(i+1)/2;
	              int m=n-i+1;
	              int cs=(m+1)/2;
	              for(int x=0;x<v;x++){
	                  if(!l[x]&& !r[x]){continue;}
	                  int y=v-1-x;
	                  int cp=min(i,x)+max(0,y-(n-i));
                 int cb=min(m,y)+max(0,x-(i-1));
	             bool pe=(cp==c-1),se=(cb==cs-1);
	             bool okl=(pe && x+1<=i)||(se && (x+1)>=i);
	             bool okr=(pe && n-y<=i)||(se && (n-y)>=i);
	             if(!okl){l[x]=0;}
	             if(!okr){r[x]=0;}
	              }     
	            }
	            if(v==n){
	                for(int x=0;x<n;x++){
	                    if(l[x]){ans+=dp[x];}
	                }
	                ans%=mod;
	            }
	            else{
	                for(int x=0;x<=v;x++){
	                    nd[x]=0;
	                }
	                for(int x=0;x<v;x++){
	                    if(!dp[x]){continue;}
	                    if(l[x]){nd[x+1]+=dp[x];if(nd[x+1]>=mod){nd[x+1]-=mod;}}
	                    if(r[x]){nd[x]+=dp[x];if(nd[x]>=mod){nd[x]-=mod;}}
	                }
	                swap(dp,nd);
	            }
	            
	        }
	        cout<<ans<<"\n";
	}
return 0;
}
